import {
  Component,
  EventEmitter,
  Input,
  Output,
  OnInit,
  signal,
} from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TravelService } from '../../../services/travel.service';
import { TranslationService } from '../../../services/translation.service';
import { Travel, TravelUpdateRequest, TravelPartner } from '../../../models/travel.model';

@Component({
  selector: 'app-edit-travel-modal',
  templateUrl: './edit-travel-modal.component.html',
  styleUrls: ['./edit-travel-modal.component.css'],
  standalone: false,
})
export class EditTravelModalComponent implements OnInit {
  @Input() travel!: Travel;
  @Input() isRTL = false;
  @Output() close = new EventEmitter<void>();
  @Output() travelUpdated = new EventEmitter<Travel>();

  travelForm: FormGroup;
  loading = signal(false);
  errorMessage = signal('');

  // Partner management
  partners = signal<TravelPartner[]>([]);
  showAddPartnerForm = signal(false);
  partnerForm: FormGroup;
  editingPartnerIndex = signal<number | null>(null);

  transportModes = [
    { value: 'Air', icon: '✈️' },
    { value: 'Train', icon: '🚄' },
    { value: 'Bus', icon: '🚌' },
    { value: 'Car', icon: '🚗' },
    { value: 'Ship', icon: '🚢' },
  ];

  constructor(
    private fb: FormBuilder,
    private travelService: TravelService,
    private translationService: TranslationService
  ) {
    this.travelForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(2),Validators.maxLength(200)]],
      destination: ['', [Validators.required, Validators.minLength(2),Validators.maxLength(100)]],
      purpose: ['', [Validators.minLength(5),Validators.maxLength(400)]],
      startDate: ['', [Validators.required]],
      endDate: ['', [Validators.required]],
      transportMode: ['Air'],
      accommodation: ['', [Validators.minLength(2),Validators.maxLength(100)]],
      isCompleted: [false],
    });

    this.partnerForm = this.fb.group({
      name: [''],
      email: [''],
      jobTitle: [''],
    });

    // Add custom validator for end date
    this.travelForm.get('endDate')?.valueChanges.subscribe(() => {
      this.validateDates();
    });
  }

  ngOnInit(): void {
    this.initializeForm();
    // Initialize partners from travel data
    if (this.travel.partners && this.travel.partners.length > 0) {
      this.partners.set([...this.travel.partners]);
    }
  }

  initializeForm(): void {
    const startDate = new Date(this.travel.startDate);
    const endDate = new Date(this.travel.endDate);

    // Format dates for datetime-local input
    const formatDateForInput = (date: Date) => {
      return date.toISOString().slice(0, 16);
    };

    this.travelForm.patchValue({
      title: this.travel.title,
      destination: this.travel.destination,
      purpose: this.travel.purpose,
      startDate: formatDateForInput(startDate),
      endDate: formatDateForInput(endDate),
      transportMode: this.travel.transportMode,
      accommodation: this.travel.accommodation,
      isCompleted: this.travel.isCompleted || false,
    });
  }

  validateDates(): void {
    const startDate = this.travelForm.get('startDate')?.value;
    const endDate = this.travelForm.get('endDate')?.value;

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);

      if (end <= start) {
        this.travelForm.get('endDate')?.setErrors({ invalidEndDate: true });
      } else {
        this.travelForm.get('endDate')?.setErrors(null);
      }
    }
  }

  onSubmit(): void {
    if (this.travelForm.valid) {
      this.loading.set(true);
      this.errorMessage.set('');

      const formValue = this.travelForm.value;
      
      // Clean partners data: set empty emails to null instead of empty string
      const cleanedPartners = this.partners().map(partner => ({
        ...partner,
        email: partner.email && partner.email.trim() ? partner.email.trim() : null as any,
        jobTitle: partner.jobTitle && partner.jobTitle.trim() ? partner.jobTitle.trim() : null as any,
      }));

      const travelData: TravelUpdateRequest = {
        title: formValue.title,
        destination: formValue.destination,
        purpose: formValue.purpose,
        startDate: new Date(formValue.startDate).toISOString(),
        endDate: new Date(formValue.endDate).toISOString(),
        transportMode: formValue.transportMode,
        accommodation: formValue.accommodation,
        isCompleted: formValue.isCompleted,
        partners: cleanedPartners,
      };

      this.travelService.updateTravel(this.travel.id, travelData).subscribe({
        next: (response) => {
          if (response.success) {
            this.travelUpdated.emit(response.data);
            this.closeModal();
          } else {
            this.errorMessage.set(
              response.message || this.translate('travel.update_error')
            );
          }
          this.loading.set(false);
        },
        error: (error) => {
          console.error('Error updating travel:', error);
          
          // Handle backend validation errors
          if (error.error?.errors) {
            const errorMessages: string[] = [];
            Object.keys(error.error.errors).forEach(key => {
              const messages = error.error.errors[key];
              if (Array.isArray(messages)) {
                errorMessages.push(...messages);
              } else {
                errorMessages.push(messages);
              }
            });
            this.errorMessage.set(errorMessages.join(', ') || this.translate('travel.update_error'));
          } else if (error.error?.message) {
            this.errorMessage.set(error.error.message);
          } else {
            this.errorMessage.set(this.translate('travel.update_error'));
          }
          
          this.loading.set(false);
        },
      });
    } else {
      this.markFormGroupTouched();
    }
  }

  markFormGroupTouched(): void {
    Object.keys(this.travelForm.controls).forEach((key) => {
      const control = this.travelForm.get(key);
      control?.markAsTouched();
    });
  }

  closeModal(): void {
    this.close.emit();
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  getTransportModeLabel(mode: string): string {
    return this.translate(`travel.transport_modes.${mode.toLowerCase()}`);
  }

  getFieldError(fieldName: string): string {
    const field = this.travelForm.get(fieldName);
    if (field?.errors && field.touched) {
      if (field.errors['required']) {
        return this.translate('common.field_required');
      }
      if (field.errors['minlength']) {
        return this.translate('common.min_length').replace(
          '%min%',
          field.errors['minlength'].requiredLength
        );
      }
      if (field.errors['maxlength']) {
        return this.translate('common.max_length').replace(
          '%max%',
          field.errors['maxlength'].requiredLength
        );
      }
      if (field.errors['invalidEndDate']) {
        return this.translate('travel.invalid_end_date');
      }
    }
    return '';
  }

  // Partner management methods
  showPartnerForm(): void {
    this.showAddPartnerForm.set(true);
    this.editingPartnerIndex.set(null);
    this.partnerForm.reset();
  }

  hidePartnerForm(): void {
    this.showAddPartnerForm.set(false);
    this.editingPartnerIndex.set(null);
    this.partnerForm.reset();
  }

  addPartner(): void {
    // Check if partner name is provided (trimmed)
    const partnerName = (this.partnerForm.value.name || '').trim();
    
    if (!partnerName) {
      // Name is required - mark as touched and show error
      this.partnerForm.get('name')?.markAsTouched();
      this.partnerForm.get('name')?.setErrors({ required: true });
      return;
    }

    // If email is provided, validate it
    const partnerEmail = (this.partnerForm.value.email || '').trim();
    if (partnerEmail && !this.isValidEmail(partnerEmail)) {
      this.partnerForm.get('email')?.markAsTouched();
      this.partnerForm.get('email')?.setErrors({ email: true });
      return;
    }

    const editIndex = this.editingPartnerIndex();
    const partnerJobTitle = (this.partnerForm.value.jobTitle || '').trim();
    const partnerData: TravelPartner = {
      id: 0, // New partner
      name: partnerName,
      email: partnerEmail || '', // Will be cleaned to null in onSubmit if empty
      jobTitle: partnerJobTitle || '',
    };

    if (editIndex !== null) {
      // Update existing partner
      this.partners.update(partners => {
        const updated = [...partners];
        updated[editIndex] = partnerData;
        return updated;
      });
    } else {
      // Add new partner
      this.partners.update(partners => [...partners, partnerData]);
    }

    this.hidePartnerForm();
  }

  private isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  editPartner(index: number): void {
    const partner = this.partners()[index];
    this.partnerForm.patchValue({
      name: partner.name,
      email: partner.email,
      jobTitle: partner.jobTitle,
    });
    this.editingPartnerIndex.set(index);
    this.showAddPartnerForm.set(true);
  }

  removePartner(index: number): void {
    this.partners.update(partners => partners.filter((_, i) => i !== index));
  }

  markPartnerFormTouched(): void {
    Object.keys(this.partnerForm.controls).forEach((key) => {
      const control = this.partnerForm.get(key);
      control?.markAsTouched();
    });
  }

  getPartnerFieldError(fieldName: string): string {
    const field = this.partnerForm.get(fieldName);
    if (field?.errors && field.touched) {
      if (field.errors['required']) {
        return this.translate('common.field_required');
      }
      if (field.errors['minlength']) {
        return this.translate('common.min_length').replace(
          '%min%',
          field.errors['minlength'].requiredLength
        );
      }
      if (field.errors['maxlength']) {
        return this.translate('common.max_length').replace(
          '%max%',
          field.errors['maxlength'].requiredLength
        );
      }
      if (field.errors['email']) {
        return this.translate('common.invalid_email');
      }
    }
    return '';
  }
}
